import { test, expect, credentialsFor } from './support/fixtures'
import { QaFailure, UI_ORIGIN } from './support/qa-api'

test('E9.routing-boundary-offline-recovery', async ({ page, context }) => {
  await context.route('**/*', route => new URL(route.request().url()).origin === UI_ORIGIN
    ? route.fallback() : route.abort('blockedbyclient'))
  await context.routeWebSocket('**/*', socket => {
    if (new URL(socket.url()).origin === 'ws://localhost:5173') socket.connectToServer()
    else socket.close()
  })
  let productWrites = 0
  page.on('request', request => {
    if (new URL(request.url()).pathname.startsWith('/api/v1/products')
        && !['GET', 'HEAD', 'OPTIONS'].includes(request.method())) productWrites++
  })
  let malformedStats = false
  let failList = false
  let abortedReads = 0
  await page.route(url => url.origin === UI_ORIGIN && url.pathname === '/api/v1/products/stats', route => {
    if (route.request().method() !== 'GET' || !malformedStats) return route.fallback()
    // Controlled invalid API shape causes a render error, without touching app source or Mongo.
    return route.fulfill({ status: 200, contentType: 'application/json', body: '{}' })
  })
  await page.route(url => url.origin === UI_ORIGIN && url.pathname === '/api/v1/products', route => {
    if (route.request().method() !== 'GET' || !failList) return route.fallback()
    abortedReads++
    return route.abort('failed')
  })

  const credentials = credentialsFor('USER')
  await page.goto('/login')
  await page.getByLabel(/^Username(?:\s*\*)?\s*$/).fill(credentials.username)
  await page.getByLabel(/^Password(?:\s*\*)?\s*$/).fill(credentials.password)
  const login = page.waitForResponse(response => new URL(response.url()).pathname === '/api/v1/auth/login'
    && response.request().method() === 'POST')
  await page.getByRole('button', { name: 'Sign in', exact: true }).click()
  const status = (await login).status()
  if (status === 429) throw new QaFailure('QA_RATE_LIMITED')
  expect(status).toBe(200)
  await expect(page).toHaveURL(`${UI_ORIGIN}/dashboard`)
  const chart = page.getByRole('img', { name: 'Bar chart showing product counts by category', exact: true })
  const metric = page.locator('.metric-card').filter({
    has: page.getByText('PRODUCTS IN CATALOGUE', { exact: true }),
  }).locator('.metric-value')
  await expect(chart).toBeVisible()
  await expect(metric).toHaveText('500')

  try {
    await test.step('unknown route renders 404 with a working return link', async () => {
      await page.goto('/qa-e9-unknown-route')
      await expect(page.getByText('404 · NOT FOUND', { exact: true })).toBeVisible()
      await expect(page.getByRole('heading', { name: 'This page wandered off.', exact: true })).toBeVisible()
      await page.getByRole('link', { name: 'Back to overview', exact: true }).click()
      await expect(page).toHaveURL(`${UI_ORIGIN}/dashboard`)
      await expect(chart).toBeVisible()
      await expect(metric).toHaveText('500')
    })

    await test.step('render failure is contained and reload restores the app', async () => {
      malformedStats = true
      await page.reload()
      const boundary = page.getByRole('alert')
      await expect(boundary).toContainText('Something went wrong')
      await expect(boundary).toContainText('We couldn’t render this page.')
      await expect(boundary).toContainText('Your saved data hasn’t been changed.')
      await expect(boundary).not.toContainText(/TypeError|\.tsx|\bat\s+\S+\s*\(|reduce is not/)
      await expect(chart).toHaveCount(0)
      malformedStats = false
      await page.getByRole('button', { name: 'Reload page', exact: true }).click()
      await expect(page).toHaveURL(`${UI_ORIGIN}/dashboard`)
      await expect(chart).toBeVisible()
      await expect(metric).toHaveText('500')
      await expect(page.getByRole('alert')).toHaveCount(0)
    })

    await test.step('failed fetch shows a safe retryable error and recovers', async () => {
      failList = true
      await page.getByRole('link', { name: 'Products', exact: true }).click()
      await expect(page.getByRole('alert')).toContainText('Products could not be loaded. Check your connection and try again.')
      expect(abortedReads).toBeGreaterThanOrEqual(2) // Original fetch and configured retry.
      await expect(page.getByRole('heading', { name: 'Products', exact: true })).toBeVisible()
      await expect(page.locator('.fatal-error')).toHaveCount(0)
      failList = false
      await page.getByRole('button', { name: 'Retry', exact: true }).click()
      await expect(page.getByText('1–10 of 500', { exact: true })).toBeVisible()
      await expect(page.getByRole('table', { name: 'Product catalogue' }).getByRole('row')).toHaveCount(11)
      await expect(page.getByRole('alert')).toHaveCount(0)
    })

    await test.step('loaded SPA remains usable offline and resumes its query online', async () => {
      await page.clock.install()
      await page.clock.pauseAt(new Date(Date.now() + 1000))
      await context.setOffline(true)
      expect(await page.evaluate(() => navigator.onLine)).toBe(false)
      const search = page.getByRole('textbox', { name: 'Search products', exact: true })
      const term = 'qa-e9-offline-no-matching-product'
      await search.fill(term)
      await page.clock.runFor(400) // Complete the app's 350-ms debounce while offline.
      await expect(search).toHaveValue(term)
      await expect(page.getByRole('heading', { name: 'Products', exact: true })).toBeVisible()
      await expect(page.locator('.fatal-error')).toHaveCount(0)
      await expect(page).toHaveURL(`${UI_ORIGIN}/products`)
      const resumed = page.waitForResponse(response => {
        const url = new URL(response.url())
        return url.origin === UI_ORIGIN && url.pathname === '/api/v1/products'
          && url.searchParams.get('q') === term && response.request().method() === 'GET'
      })
      await context.setOffline(false)
      await page.clock.resume()
      expect((await resumed).status()).toBe(200)
      await expect(page.getByText('Nothing in this view yet', { exact: true })).toBeVisible()
      await page.getByRole('button', { name: 'Clear', exact: true }).click()
      await expect(search).toHaveValue('')
      await expect(page.getByText('1–10 of 500', { exact: true })).toBeVisible()
      await expect(page.getByRole('alert')).toHaveCount(0)
    })

    const final = await page.evaluate(async () => {
      const response = await fetch('/api/v1/products?page=0&size=1', { credentials: 'include' })
      const body = await response.json()
      return { status: response.status, count: body.totalElements }
    })
    expect(final).toEqual({ status: 200, count: 500 })
    expect(productWrites).toBe(0)
  } finally {
    malformedStats = false
    failList = false
    await context.setOffline(false)
    await page.clock.resume()
  }
})

// Pure extraction of G4's canonicalizer; keep inventory serialization unchanged.
export function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical)
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])]))
  }
  return value
}

/** Match a literal label, preserving the existing optional required-marker/whitespace suffix. */
export function formLabelPattern(label: string): RegExp {
  const literal = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  return new RegExp(`^${literal}(?:\\s*\\*)?\\s*$`)
}

// G4 only: node frontend/e2e/support/mongo-user-metadata.mjs --approved-metadata
// Requires per-run approval for the Mongo-container credential-scope exception.
// Credentials are referenced ONLY inside mongosh's existing container env;
// never returned, put in command arguments, read from .env, or logged.
// No user documents/password hashes are fetched; output is counts/index flags.
import { execFile } from 'node:child_process'
import { promisify } from 'node:util'
import { fileURLToPath } from 'node:url'

const execute = promisify(execFile)
const root = fileURLToPath(new URL('../../../', import.meta.url)).replace(/\/$/, '')
const marker = 'QA_USER_METADATA:'
const script = String.raw`
try {
  if (!process.env.MONGO_INITDB_ROOT_USERNAME || !process.env.MONGO_INITDB_ROOT_PASSWORD) {
    print('QA_USER_METADATA:' + JSON.stringify({ failure: 'QA_CONTAINER_CREDENTIALS_MISSING' })); quit(1);
  }
  const admin = db.getSiblingDB('admin');
  const authenticated = admin.auth(process.env.MONGO_INITDB_ROOT_USERNAME, process.env.MONGO_INITDB_ROOT_PASSWORD);
  if (!(authenticated === 1 || authenticated?.ok === 1)) {
    print('QA_USER_METADATA:' + JSON.stringify({ failure: 'QA_MONGO_AUTH_FAILED' })); quit(1);
  }
  const databases = admin.runCommand({ listDatabases: 1, nameOnly: true, authorizedDatabases: true });
  if (databases.ok !== 1) throw new Error();
  const candidates = databases.databases.filter(item => !['admin', 'config', 'local'].includes(item.name))
    .filter(item => {
      const collections = db.getSiblingDB(item.name).runCommand({ listCollections: 1, nameOnly: true,
        filter: { name: { $in: ['products', 'users'] } }, maxTimeMS: 3000 });
      if (collections.ok !== 1) throw new Error();
      const names = collections.cursor.firstBatch.map(collection => collection.name);
      return names.includes('products') && names.includes('users');
    });
  if (candidates.length !== 1) {
    print('QA_USER_METADATA:' + JSON.stringify({ failure: 'QA_APP_DATABASE_NOT_UNIQUE', candidates: candidates.length })); quit(1);
  }
  const application = db.getSiblingDB(candidates[0].name);
  const users = application.getCollection('users');
  const count = filter => users.countDocuments(filter, { maxTimeMS: 3000 });
  const duplicates = users.aggregate([
    { $group: { _id: '$username', count: { $sum: 1 } } },
    { $match: { count: { $gt: 1 } } }, { $count: 'groups' }
  ], { maxTimeMS: 3000 }).toArray();
  const uniqueIndex = users.getIndexes().some(index => index.unique === true
    && !index.sparse && !index.partialFilterExpression
    && Object.keys(index.key).length === 1 && index.key.username === 1);
  print('QA_USER_METADATA:' + JSON.stringify({ database: candidates[0].name,
    productsCount: application.getCollection('products').countDocuments({}, { maxTimeMS: 3000 }),
    usersCount: count({}), adminCount: count({ username: 'admin' }), userCount: count({ username: 'user' }),
    duplicateUsernameGroups: duplicates[0]?.groups || 0, uniqueUsernameIndex: uniqueIndex }));
} catch {
  print('QA_USER_METADATA:' + JSON.stringify({ failure: 'QA_MONGO_METADATA_OPERATION_FAILED' })); quit(1);
}`

try {
  if (!process.argv.includes('--approved-metadata')) throw new Error('QA_METADATA_APPROVAL_REQUIRED')
  const listed = await execute('docker', ['ps', '--filter', `label=com.docker.compose.project.working_dir=${root}`,
    '--filter', 'label=com.docker.compose.service=mongodb', '--format', '{{.ID}}'], { timeout: 10_000 })
  const ids = listed.stdout.trim().split('\n').filter(Boolean)
  if (ids.length !== 1 || !/^[a-f0-9]{12,64}$/.test(ids[0])) throw new Error('QA_CONTAINER_NOT_UNIQUE')
  let output
  try {
    output = (await execute('docker', ['exec', ids[0], 'mongosh', '--quiet', '--eval', script],
      { timeout: 30_000, maxBuffer: 32_768 })).stdout
  } catch (error) {
    // Ignore potentially sensitive CLI stderr; only parse our explicit marker.
    output = typeof error.stdout === 'string' ? error.stdout : ''
  }
  const line = output.split('\n').find(item => item.startsWith(marker))
  if (!line) throw new Error('QA_METADATA_RESULT_MISSING')
  const result = JSON.parse(line.slice(marker.length))
  if (result.failure) {
    const allowed = ['QA_CONTAINER_CREDENTIALS_MISSING', 'QA_MONGO_AUTH_FAILED',
      'QA_APP_DATABASE_NOT_UNIQUE', 'QA_MONGO_METADATA_OPERATION_FAILED']
    throw new Error(allowed.includes(result.failure) ? result.failure : 'QA_METADATA_RESULT_INVALID')
  }
  const keys = ['database', 'productsCount', 'usersCount', 'adminCount', 'userCount',
    'duplicateUsernameGroups', 'uniqueUsernameIndex']
  if (Object.keys(result).length !== keys.length || !keys.every(key => Object.hasOwn(result, key))
    || typeof result.database !== 'string' || !/^[a-zA-Z0-9_-]{1,64}$/.test(result.database)
    || !keys.slice(1, -1).every(key => Number.isSafeInteger(result[key]) && result[key] >= 0)
    || typeof result.uniqueUsernameIndex !== 'boolean') throw new Error('QA_METADATA_RESULT_INVALID')
  console.log(JSON.stringify({ item: 'G4', ...result }))
} catch (error) {
  const allowed = new Set(['QA_METADATA_APPROVAL_REQUIRED', 'QA_CONTAINER_NOT_UNIQUE',
    'QA_METADATA_RESULT_MISSING', 'QA_METADATA_RESULT_INVALID', 'QA_CONTAINER_CREDENTIALS_MISSING',
    'QA_MONGO_AUTH_FAILED', 'QA_APP_DATABASE_NOT_UNIQUE', 'QA_MONGO_METADATA_OPERATION_FAILED'])
  console.log(JSON.stringify({ item: 'G4', failure: allowed.has(error.message) ? error.message : 'QA_METADATA_OPERATION_FAILED' }))
  process.exitCode = 1
}

import type { FullResult, Reporter, Suite, TestCase, TestError, TestResult } from '@playwright/test/reporter'
import { safeReason } from './qa-api'

/** Never serialize raw errors, titles, call logs, stdout, bodies or headers. */
export function resultRecord(title: string, status: TestResult['status'], durationMs: number,
  errors: readonly { message?: string }[]) {
  const id = title.match(/^E[1-9](?:\.[a-z0-9-]{1,40})?(?=\s|$)/i)?.[0] ?? 'SETUP'
  return {
    id, status, durationMs,
    ...(status === 'failed' || status === 'timedOut' || status === 'interrupted'
      ? { reason: safeReason(errors) } : {}),
  }
}

export default class SafeReporter implements Reporter {
  printsToStdio() { return true }
  onBegin(_config: unknown, suite: Suite) {
    process.stdout.write(`${JSON.stringify({ phase: 'start', tests: suite.allTests().length })}\n`)
  }
  onTestEnd(test: TestCase, result: TestResult) {
    process.stdout.write(`${JSON.stringify(resultRecord(test.title, result.status, result.duration, result.errors))}\n`)
  }
  onError(error: TestError) {
    const message = error.message ?? ''
    const reason = /No tests found/i.test(message) ? 'QA_NO_TESTS_DISCOVERED'
      : /fixture|destructuring/i.test(message) ? 'QA_FIXTURE_CONFIGURATION'
        : /Cannot find|Cannot load|module/i.test(message) ? 'QA_MODULE_RESOLUTION'
          : /browser|executable/i.test(message) ? 'QA_BROWSER_UNAVAILABLE'
            : 'QA_RUNNER_ERROR'
    process.stdout.write(`${JSON.stringify({ reason })}\n`)
  }
  onStdOut() { /* Deliberately discard worker output. */ }
  onStdErr() { /* Deliberately discard worker output. */ }
  onEnd(result: FullResult) {
    process.stdout.write(`${JSON.stringify({ phase: 'end', status: result.status })}\n`)
  }
}

/** The existing backend-compatible price grammar, unchanged: positive, 12 whole digits, 2 decimals. */
export function isValidProductPrice(value: string): boolean {
  return /^\d{1,12}(\.\d{1,2})?$/.test(value) && Number(value) > 0
}
